local P={}
P.root='/Users/ryanmorrison/Documents/Codex/2026-10-25/visit-https-cerebralvalley-ai-e-meta/outputs/godmode/art/cozy'
P.hex={'352b27','3a4a46','687265','8a9380','b6b9a0','f0ddb2','fff0cc','5a3b2b','7b5037','a67548','c99b64','e3bd80','503d2d','725337','b18351','d0ae77','344d33','4f7441','719550','91ad5c','b4ca7a','d6d995','1f3f32','2f5a3b','47764b','6c9859','9dbb75','224b54','386d73','5c9695','8cbbb1','c9dacf','593a35','7e4c3e','a46647','c78d59','e0b178','7b612d','b88a3d','e5bc64','744b38','ac7350','dbb08a','f4d1aa','ba7271','2e5360','4d7d88','89adb0','753f44','ad6660','d69885','b6b59b','dfd7b4','f3e5c3','514760','877b96','bbb0bd','855f35','bc9759','e0c48a','192d2b','d8be8e','413b2d','f6da91'}
P.colors={}
for i,h in ipairs(P.hex) do P.colors[i]=app.pixelColor.rgba(tonumber(h:sub(1,2),16),tonumber(h:sub(3,4),16),tonumber(h:sub(5,6),16),255) end
function P.col(c) return type(c)=='number' and P.colors[c] or c end
function P.image(w,h) local im=Image(w,h,ColorMode.RGB); im:clear();return im end
function P.p(im,x,y,c) x=math.floor(x);y=math.floor(y);if x>=0 and y>=0 and x<im.width and y<im.height then im:drawPixel(x,y,P.col(c)) end end
function P.rect(im,x,y,w,h,c) for yy=math.max(0,math.floor(y)),math.min(im.height-1,math.floor(y+h-1)) do for xx=math.max(0,math.floor(x)),math.min(im.width-1,math.floor(x+w-1)) do im:drawPixel(xx,yy,P.col(c)) end end end
function P.line(im,x0,y0,x1,y1,c) x0=math.floor(x0);y0=math.floor(y0);x1=math.floor(x1);y1=math.floor(y1);local dx=math.abs(x1-x0);local sx=x0<x1 and 1 or -1;local dy=-math.abs(y1-y0);local sy=y0<y1 and 1 or -1;local er=dx+dy;while true do P.p(im,x0,y0,c);if x0==x1 and y0==y1 then break end;local e=2*er;if e>=dy then er=er+dy;x0=x0+sx end;if e<=dx then er=er+dx;y0=y0+sy end end end
function P.ellipse(im,cx,cy,rx,ry,c) for y=math.floor(cy-ry),math.ceil(cy+ry) do for x=math.floor(cx-rx),math.ceil(cx+rx) do if ((x-cx)/rx)^2+((y-cy)/ry)^2<=1 then P.p(im,x,y,c) end end end end
function P.poly(im,pts,c) local miny=100000;local maxy=-100000;for _,p in ipairs(pts) do miny=math.min(miny,p[2]);maxy=math.max(maxy,p[2]) end;for y=math.floor(miny),math.ceil(maxy) do local xs={};for i,a in ipairs(pts) do local b=pts[i%#pts+1];if (a[2]<=y and b[2]>y) or (b[2]<=y and a[2]>y) then xs[#xs+1]=a[1]+(y-a[2])/(b[2]-a[2])*(b[1]-a[1]) end end;table.sort(xs);for i=1,#xs,2 do if xs[i+1] then P.line(im,math.ceil(xs[i]),y,math.floor(xs[i+1]),y,c) end end end end
function P.hash(x,y,s) return (x*107+y*389+(s or 1)*7919+x*y*17)%997 end
function P.noise(im,x,y,w,h,base,low,high,seed,amount) P.rect(im,x,y,w,h,base);for yy=y,y+h-1 do for xx=x,x+w-1 do local n=P.hash(xx,yy,seed);if n<(amount or 60) then P.p(im,xx,yy,low) elseif n>997-(amount or 60) then P.p(im,xx,yy,high) end end end end
function P.outline(im,c) local cp=im:clone();for y=0,im.height-1 do for x=0,im.width-1 do if app.pixelColor.rgbaA(cp:getPixel(x,y))==0 then local hit=false;for _,d in ipairs({{-1,0},{1,0},{0,-1},{0,1}}) do local xx=x+d[1];local yy=y+d[2];if xx>=0 and yy>=0 and xx<im.width and yy<im.height and app.pixelColor.rgbaA(cp:getPixel(xx,yy))>0 then hit=true end end;if hit then P.p(im,x,y,c) end end end end end
function P.saveImage(im,path) im:saveAs(path) end
function P.saveSprite(im,path,layerName) local s=Sprite(im.width,im.height,ColorMode.RGB);s.layers[1].name=layerName or 'Original pixels';if s.cels[1] then s:deleteCel(s.cels[1]) end;s:newCel(s.layers[1],1,im,Point(0,0));local pal=Palette(#P.hex);for i,h in ipairs(P.hex) do pal:setColor(i-1,Color{r=tonumber(h:sub(1,2),16),g=tonumber(h:sub(3,4),16),b=tonumber(h:sub(5,6),16),a=255}) end;s:setPalette(pal);s:saveAs(path);return s end
function P.json(path,data) local f=assert(io.open(path,'w'));f:write(json.encode(data));f:write('\n');f:close() end
function P.atlas(name,w,h) local a={name=name,image=P.image(w,h),frames={},animations={},x=2,y=2,row=0,w=w,h=h,count=0};function a:add(key,im,duration,anchor) if self.x+im.width+2>self.w then self.x=2;self.y=self.y+self.row+2;self.row=0 end;assert(self.y+im.height+2<=self.h,'Atlas overflow '..key);self.image:drawImage(im,Point(self.x,self.y));self.frames[key]={frame={x=self.x,y=self.y,w=im.width,h=im.height},rotated=false,trimmed=false,spriteSourceSize={x=0,y=0,w=im.width,h=im.height},sourceSize={w=im.width,h=im.height},duration=duration or 200,anchor={x=(anchor and anchor.x or math.floor(im.width/2))/im.width,y=(anchor and anchor.y or im.height-1)/im.height},pixelAnchor=anchor or {x=math.floor(im.width/2),y=im.height-1}};self.x=self.x+im.width+2;self.row=math.max(self.row,im.height);self.count=self.count+1;return key end;function a:alias(key,other) assert(self.frames[other],other);self.frames[key]=self.frames[other] end;function a:save() local pub=P.root..'/../../public/assets/cozy/';P.saveImage(self.image,pub..self.name..'.png');P.saveSprite(self.image,P.root..'/'..self.name..'.aseprite',self.name..' atlas');local actual={}local found={}for yy=0,self.image.height-1 do for xx=0,self.image.width-1 do local col=self.image:getPixel(xx,yy);if app.pixelColor.rgbaA(col)>0 and not found[col]then found[col]=true;actual[#actual+1]=string.format('%02x%02x%02x%02x',app.pixelColor.rgbaR(col),app.pixelColor.rgbaG(col),app.pixelColor.rgbaB(col),app.pixelColor.rgbaA(col))end end end;table.sort(actual);local meta={app='GODMODE original native Aseprite authoring',version='1',image=self.name..'.png',format='RGBA8888',size={w=self.w,h=self.h},scale='1',palette=actual,lighting='upper-left',frameCount=self.count,anchorUnits='normalized',pixelAnchorUnits='native pixels'};for k,v in pairs(self.metadata or {}) do meta[k]=v end;P.json(pub..self.name..'.json',{frames=self.frames,animations=self.animations,meta=meta});print(self.name..': '..self.count..' source frames') end;return a end
return P
